def solve():
    num_vertices = 18
    fixed_edges = [
        (3,15), (11,13), (13,17), (2,11), (11,17), (2,12), (7,17), (9,17), (3,5), (0,16),
        (1,14), (7,9), (0,9), (6,11), (3,11), (0,2), (1,17), (4,8), (5,15), (1,15),
        (2,15), (15,17), (4,16), (0,8), (4,6), (8,13), (13,14), (2,10), (6,13), (9,12)
    ]

    adj = {i: set() for i in range(num_vertices)}
    for u, v in fixed_edges:
        adj[u].add(v)
        adj[v].add(u)

    def get_degrees():
        return {i: len(adj[i]) for i in range(num_vertices)}

    degrees = get_degrees()

    # Need to add edges to make all degrees >= 5
    # Vertices needing edges:
    # 0: 4, 1: 3, 3: 3, 4: 3, 5: 2, 6: 3, 7: 2, 8: 3, 9: 4, 10: 1, 12: 2, 14: 2, 16: 2

    # Let's try to add edges greedily
    for i in range(num_vertices):
        while len(adj[i]) < 5:
            # Find another vertex that also needs an edge
            found = False
            for j in range(i + 1, num_vertices):
                if len(adj[j]) < 5 and j not in adj[i] and i != j:
                    adj[i].add(j)
                    adj[j].add(i)
                    found = True
                    break
            if not found:
                # If no other vertex needs an edge, just connect to any vertex that isn't already connected
                for j in range(num_vertices):
                    if j not in adj[i] and i != j:
                        adj[i].add(j)
                        adj[j].add(i)
                        found = True
                        break
            if not found:
                return None # Should not happen

    return adj

